import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"跟做：在 Electron 桌面壳中复用同一套页面","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/electron-shell.md","filePath":"tutorials/electron-shell.md"}'),i={name:"tutorials/electron-shell.md"};function l(d,e,r,c,n,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="跟做-在-electron-桌面壳中复用同一套页面" tabindex="-1">跟做：在 Electron 桌面壳中复用同一套页面 <a class="header-anchor" href="#跟做-在-electron-桌面壳中复用同一套页面" aria-label="Permalink to &quot;跟做：在 Electron 桌面壳中复用同一套页面&quot;">​</a></h1><p>本章回答“桌面端从哪里来”。桌面壳不是第二套业务：它把浏览器访问的同源 Web 入口装进 Electron 窗口，业务页面、API 合同和会话 Cookie 全部来自共享代码。没有离线编辑，也没有另一套登录协议。</p><h2 id="_1-启动组合并打开桌面壳" tabindex="-1">1. 启动组合并打开桌面壳 <a class="header-anchor" href="#_1-启动组合并打开桌面壳" aria-label="Permalink to &quot;1. 启动组合并打开桌面壳&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p><code>just dev</code> 照常启动 PostgreSQL/RustFS/Redis、API 与 Web；<code>just desktop</code> 在 Electron 窗口中加载同一个 Web 入口（默认 <a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a>，可用 <code>.env</code> 的 <code>SAAS_DESKTOP_ORIGIN</code> 或 <code>WEB_PORT</code> 调整）。在壳中注册、登录、打开“我的文档”并预览 Markdown，行为与浏览器完全一致：页面由同一份 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/b68469827933d0391905ca16bfc8a73ddc58df31/apps/web/src/router.tsx" target="_blank" rel="noreferrer">Web 路由</a>渲染，请求由同一份生成 SDK 发出。</p><p>会话 Cookie 保存在壳的独立持久分区 <code>persist:saas-desktop</code> 中，与系统浏览器互不影响；重启壳后登录仍然有效。退出登录会撤销服务端 Session，壳与浏览器中的对应会话同时失效。</p><h2 id="_2-壳只做平台接线-不做业务" tabindex="-1">2. 壳只做平台接线，不做业务 <a class="header-anchor" href="#_2-壳只做平台接线-不做业务" aria-label="Permalink to &quot;2. 壳只做平台接线，不做业务&quot;">​</a></h2><p>壳的实现只有三个部分：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/b68469827933d0391905ca16bfc8a73ddc58df31/apps/desktop/src/main.ts" target="_blank" rel="noreferrer">主进程</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/b68469827933d0391905ca16bfc8a73ddc58df31/apps/desktop/src/preload.ts" target="_blank" rel="noreferrer">preload 桥</a>和一份本地错误页。窗口创建时固定 <code>contextIsolation: true</code>、<code>nodeIntegration: false</code>、<code>sandbox: true</code>，并禁用 <code>&lt;webview&gt;</code>。渲染进程接触不到 Node，也接触不到 Session secret——它只是加载同源页面，Cookie 留在 Chromium 的网络栈里，从不进入 IPC。</p><p>导航约束在壳层强制：</p><ul><li>只允许加载应用同源地址；页面里指向外部站点的链接不会把窗口带走，而是通过系统浏览器打开（仅接受 http/https，其他 scheme 直接忽略）。</li><li><code>window.open</code>/<code>target=&quot;_blank&quot;</code> 弹窗一律拒绝；外链仍走系统浏览器。</li><li>网站权限请求（摄像头、通知等）默认全部拒绝。</li><li>证书错误按 Chromium 默认策略拒绝，壳不做任何放行。</li></ul><p>preload 通过 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/b68469827933d0391905ca16bfc8a73ddc58df31/apps/desktop/src/ipc-contract.ts" target="_blank" rel="noreferrer">IPC 合同</a> 只暴露四个能力：读取壳版本/平台、重试加载、打开下载目录，以及订阅下载状态事件。每个载荷在两侧都经过合同校验，格式不对的事件直接丢弃；外链转交系统浏览器的 http/https-only 策略同样是合同的一部分。合同没有秘密字段，也没有文件内容——文件由主进程写盘，不经 IPC 传输。</p><h2 id="_3-受控的深链与下载入口" tabindex="-1">3. 受控的深链与下载入口 <a class="header-anchor" href="#_3-受控的深链与下载入口" aria-label="Permalink to &quot;3. 受控的深链与下载入口&quot;">​</a></h2><p>深链形如 <code>saas://open/&lt;应用内路径&gt;</code>。主进程解析后要求：协议必须是 <code>saas:</code>、主机必须是 <code>open</code>，路径必须是本应用同源绝对路径（绝对 URL、协议相对路径、反斜杠绕过、原始空白字符都会被拒绝）。合法深链让已存在的窗口聚焦并导航到该页面，例如把 <code>saas://open/notifications</code> 发给运行中的壳，窗口会聚焦并打开通知页。无效深链被静默忽略，不导航也不记录目标内容。壳使用单实例锁：第二次启动只聚焦已有窗口并处理深链，不会开第二个窗口。</p><p>下载入口监听分区的 <code>will-download</code> 事件：只有应用同源页面发起的下载被接受，保存到系统下载目录的 <code>SaasTemplate</code> 子目录（可用 <code>SAAS_DESKTOP_DOWNLOADS_DIR</code> 覆盖），同名文件自动追加序号，不覆盖已有文件。共享页面中的附件/导出下载正是通过页面内 blob 触发这条路径；跨源页面发起的下载会被直接取消。下载进度与结果通过合同事件通知页面，文件名经过清洗，永远只是一个安全的文件名。</p><p>壳的窗口在主文档加载失败时切换到本地错误页，点击“重新连接”回到失败前的应用地址。渲染进程崩溃同样回到错误页，不会留下白窗口。关闭最后一个窗口即退出应用；协议注册失败不影响开发使用（深链仍可通过第二实例参数送达）。</p><h2 id="_4-测试与-ci-分工" tabindex="-1">4. 测试与 CI 分工 <a class="header-anchor" href="#_4-测试与-ci-分工" aria-label="Permalink to &quot;4. 测试与 CI 分工&quot;">​</a></h2><ul><li><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/b68469827933d0391905ca16bfc8a73ddc58df31/apps/desktop/src/ipc-contract.test.ts" target="_blank" rel="noreferrer">IPC 合同测试</a>（Vitest）：校验桥形状、深链路径归一化、文件名清洗与下载事件校验，无需启动 GUI，进入默认 <code>just check</code>。</li><li>壳级 GUI smoke：<code>just desktop-smoke</code> 启动真实栈（PostgreSQL/RustFS/Redis/Mailpit/API/Web），用 Playwright 驱动真实 Electron：启动、登录/退出、知识库文档浏览与 Markdown 预览、应用页下载落盘与跨源下载拒绝、外链转交系统浏览器、深链合法/非法目标、断网错误页与重试恢复。业务角色矩阵不在这里重复，沿用后端与共享 View 测试。</li><li>CI 把 GUI smoke 放在独立的 <code>desktop-smoke</code> job（无显示环境由 <code>xvfb-run</code> 提供 X server）；默认主门禁只包含壳的类型、构建与合同检查。</li></ul><h2 id="_5-运行本章检查" tabindex="-1">5. 运行本章检查 <a class="header-anchor" href="#_5-运行本章检查" aria-label="Permalink to &quot;5. 运行本章检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop-smoke</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>重点是无 secret 的 IPC 合同、同源导航约束、深链拒绝外部目标、下载只来自应用页面且不覆盖文件，以及错误页可恢复。壳依赖 Electron 与桌面环境，属于可选运行时：默认开发与 <code>just check</code> 不要求安装桌面工具链之外的组件。</p><p>打包分发（安装包、自动更新、多平台签名）不在模板 v1 范围内；<code>pnpm --filter @saas/desktop build</code> 产出的 <code>dist/main.cjs</code> 可直接交给任何标准 Electron 打包流程。</p><hr><p>源码版本：<code>b68469827933</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/b68469827933d0391905ca16bfc8a73ddc58df31/docs/tutorials/20-electron-shell.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,23)])])}const b=a(i,[["render",l]]);export{k as __pageData,b as default};
